import Foundation
import SeedAnchorGenCore
import Testing

private let header = """
// AUTO-GENERATED by Tools/SeedAnchorGen — DO NOT EDIT.
// Source: Alfie-BFF src/mock/fixtures/seed-anchors.json. Regenerate: ./Alfie/scripts/generate-seed-anchors.sh
// swiftlint:disable all

"""

private func source(_ json: String) throws -> String {
    try SeedAnchorsGenerator.swiftSource(fromJSON: Data(json.utf8))
}

@Suite("SeedAnchorsGenerator")
struct SeedAnchorsGeneratorTests {
    @Test("a top-level string anchor becomes a static constant under its own key")
    func topLevelString() throws {
        let expected = header + """
        public enum SeedAnchors {
            public static let unknownBarcode = "0000000000000"
        }

        """
        #expect(try source(#"{ "unknownBarcode": "0000000000000" }"#) == expected)
    }

    @Test("an anchor group becomes a nested enum named after its key, with keyword keys escaped")
    func nestedGroup() throws {
        let expected = header + """
        public enum SeedAnchors {
            public enum Products {
                public static let `default` = "alfie-oxford-shirt"
                public static let oneImage = "harbour-pleated-midi-skirt"
            }
        }

        """
        let json = #"{ "products": { "default": "alfie-oxford-shirt", "oneImage": "harbour-pleated-midi-skirt" } }"#
        #expect(try source(json) == expected)
    }

    @Test("a group whose enum name is a Swift keyword is escaped")
    func keywordGroupName() throws {
        let expected = header + """
        public enum SeedAnchors {
            public enum `Type` {
                public static let shirt = "shirt"
            }
        }

        """
        #expect(try source(#"{ "type": { "shirt": "shirt" } }"#) == expected)
    }

    @Test("the same anchors give the same source whatever order the JSON lists them in")
    func keyOrderIndependent() throws {
        let one = #"{ "menuHandle": "main-menu", "collections": { "women": "women", "men": "men" } }"#
        let other = #"{ "collections": { "men": "men", "women": "women" }, "menuHandle": "main-menu" }"#
        #expect(try source(one) == source(other))
    }

    @Test("a value with quotes and backslashes stays one valid string literal")
    func escapesStringValues() throws {
        let expected = header + """
        public enum SeedAnchors {
            public static let term = "5\\" \\\\ heel"
        }

        """
        #expect(try source(#"{ "term": "5\" \\ heel" }"#) == expected)
    }

    @Test(
        "an anchor the generator can't mirror fails, naming its path",
        arguments: [
            (#"{ "barcode": { "length": 13 } }"#, "barcode.length"),
            (#"{ "inStock": true }"#, "inStock"),
            (#"{ "variantIds": ["a", 2] }"#, "variantIds"),
            (#"{ "search-terms": { "many": "shirt" } }"#, "search-terms"),
            (#"{ "many\n": "shirt" }"#, "many\n"),
            (#"["women"]"#, "<root>"),
        ]
    )
    func unsupportedAnchor(json: String, path: String) {
        #expect(throws: SeedAnchorsError.unsupportedAnchor(path: path)) {
            try source(json)
        }
    }

    @Test("a group and a sibling anchor that would share one Swift name fail, naming the anchor")
    func nameCollision() {
        #expect(throws: SeedAnchorsError.duplicateName(path: "products")) {
            try source(#"{ "Products": "x", "products": { "default": "alfie-oxford-shirt" } }"#)
        }
    }

    @Test("a list anchor becomes a string array in the BFF's order")
    func stringList() throws {
        let expected = header + """
        public enum SeedAnchors {
            public static let relatedProductSlugs: [String] = [
                "alfie-poplin-shirt",
                "alfie-linen-camp-shirt",
            ]
        }

        """
        #expect(try source(#"{ "relatedProductSlugs": ["alfie-poplin-shirt", "alfie-linen-camp-shirt"] }"#) == expected)
    }
}
